package com.bank.spark.service;

import java.util.logging.Logger;

// Models the unified memory region with a dynamic execution/storage boundary.
public class UnifiedMemory {

    private static final Logger log = Logger.getLogger(UnifiedMemory.class.getName());

    private final long unifiedMb;          // total unified region
    private final long storageBaselineMb;  // protected storage floor
    private long executionUsed = 0;
    private long storageUsed = 0;

    public UnifiedMemory(long unifiedMb, double storageFraction) {
        this.unifiedMb = unifiedMb;
        this.storageBaselineMb = (long) (unifiedMb * storageFraction);
    }

    private long free() { return unifiedMb - executionUsed - storageUsed; }

    // Storage requests memory (cache/persist); may use free space only.
    public boolean requestStorage(long mb) {
        if (mb <= free()) {
            storageUsed += mb;
            log.info(() -> "Storage cached " + mb + "MB (storageUsed=" + storageUsed + ")");
            return true;
        }
        log.warning(() -> "Storage request " + mb + "MB refused (free=" + free() + "); block not cached");
        return false;
    }

    // Execution requests memory; may evict storage ABOVE the protected baseline.
    public boolean requestExecution(long mb) {
        if (mb <= free()) {
            executionUsed += mb;
            log.info(() -> "Execution acquired " + mb + "MB from free space");
            return true;
        }
        long evictable = Math.max(0, storageUsed - storageBaselineMb);
        long needed = mb - free();
        if (needed <= evictable) {
            storageUsed -= needed;                       // evict borrowed cached blocks
            executionUsed += mb;
            log.warning(() -> "Execution evicted " + needed + "MB of cached storage (priority)");
            return true;
        }
        log.severe(() -> "Execution needs " + mb + "MB but only " + (free() + evictable)
                + "MB reclaimable → SPILL to disk");
        return false;   // would spill in real Spark
    }
}
