package com.bank.spark;

import com.bank.spark.service.UnifiedMemory;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: borrowing and eviction in the unified memory model.
public class MemoryModelDemo {

    private static final Logger log = Logger.getLogger(MemoryModelDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Unified region of 1000 MB, storage baseline 50% = 500 MB.
        UnifiedMemory mem = new UnifiedMemory(1000, 0.5);

        log.info("Cache the accounts reference dataset (storage borrows idle space)");
        mem.requestStorage(700);  // storage uses 700, above its 500 baseline

        log.info("Transactions join needs execution memory");
        mem.requestExecution(600); // free=300; evict 200 of borrowed storage (700→500)

        log.info("Another aggregation needs still more execution memory");
        mem.requestExecution(500); // cannot reclaim below baseline → spill

        log.info("Unified memory model demo complete.");
    }
}
